import {readFileSync,writeFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {execFileSync} from 'node:child_process';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {instrumentTypeScriptWithCoverage,isCoverageIgnored} from '../scripts/run-istanbul-bun-coverage';
import {sourceHash} from '../scripts/quality-inventory';
const root='.planning/memory-resilience/';
const catalog=JSON.parse(readFileSync(root+'executable-catalog.json','utf8'));
const manifest=JSON.parse(readFileSync(root+'quality-classifications.json','utf8'));
const started=new Date().toISOString();
const rows=[];
for(const file of catalog.files){
 const source=readFileSync(file.path,'utf8');
 if(sourceHash(source)!==file.sourceHash)throw Error('Stale source '+file.path);
 const proposed=manifest.files.find((x:any)=>x.path===file.path).applicability;
 const row:any={path:file.path,sourceHash:file.sourceHash,syntax:file.syntax,proposedMode:proposed.mode,currentRunnerSelects:file.path.startsWith('src/')&&file.path.endsWith('.ts')&&!isCoverageIgnored(file.path)};
 if(file.syntax==='browser-code'){row.status='separate-runtime-required';rows.push(row);continue;}
 try {
  const instrumented=instrumentTypeScriptWithCoverage(source,resolve(file.path));
  const data=instrumented.coverageData;
  const summary=createCoverageMap({[data.path]:data}).getCoverageSummary().data;
  row.status='instrumented-without-execution';
  row.metrics=Object.fromEntries(['statements','branches','functions','lines'].map(metric=>[metric,{total:summary[metric].total,covered:summary[metric].covered}]));
  row.instrumentedHash=sourceHash(instrumented.code);
  row.mapHash=sourceHash(JSON.stringify({statementMap:data.statementMap,fnMap:data.fnMap,branchMap:data.branchMap}));
  row.nonzeroMetrics=Object.keys(row.metrics).filter(metric=>row.metrics[metric].total>0);
 } catch(error){row.status='instrumentation-error';row.error=String(error);}
 rows.push(row);
}
const result={item_id:'B04',source_revision:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),cwd:process.cwd(),started_at:started,finished_at:new Date().toISOString(),command:'bun .git/b04-applicability-probe.ts',runtime:Bun.version,scope:'Static instrumentation only; no candidate module evaluated, test suite invoked, model downloaded or generated program run.',instrumenterSourceHash:sourceHash(readFileSync('scripts/run-istanbul-bun-coverage.ts','utf8')),probeSource:readFileSync('.git/b04-applicability-probe.ts','utf8'),rows};
writeFileSync('.git/b04-applicability-probe.json',JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify({count:rows.length,statuses:Object.fromEntries([...new Set(rows.map(x=>x.status))].map(status=>[status,rows.filter(x=>x.status===status).length])),currentRunnerSelected:rows.filter(x=>x.currentRunnerSelects).length,zeroCounterFiles:rows.filter(x=>x.metrics&&x.nonzeroMetrics.length===0).map(x=>x.path),errors:rows.filter(x=>x.status==='instrumentation-error')}));

