import fs from 'node:fs';
import ts from 'typescript';
import crypto from 'node:crypto';
const root='.planning/memory-resilience/';
const read=p=>JSON.parse(fs.readFileSync(p,'utf8'));
const save=(p,x)=>fs.writeFileSync(p,JSON.stringify(x,null,2)+'\n');
const hash=p=>crypto.createHash('sha256').update(fs.readFileSync(p,'utf8').replaceAll('\r\n','\n')).digest('hex');
const probe=read('.git/b04-applicability-probe.json');
const boundary=read('.git/b04-counter-boundary-probe.json');
const manifest=read(root+'quality-classifications.json');
const ledger=read(root+'work-items.json');
if(ledger.items.length!==215||ledger.items.some(x=>x.id==='B05.1'))throw Error('Unexpected ledger start');
for(const row of probe.rows){
 if(hash(row.path)!==row.sourceHash)throw Error('Stale source '+row.path);
 const file=manifest.files.find(x=>x.path===row.path);
 let features={optionalChainSites:0,defaultExportExpressions:0};
 if(row.syntax!=='browser-code'){
  const source=fs.readFileSync(row.path,'utf8');
  const emitted=ts.transpileModule(source,{compilerOptions:{target:ts.ScriptTarget.ESNext,module:ts.ModuleKind.ESNext,verbatimModuleSyntax:true,removeComments:true}}).outputText;
  const parsed=ts.createSourceFile('probe.js',emitted,ts.ScriptTarget.ESNext,true,ts.ScriptKind.JS);
  const visit=n=>{if(n.questionDotToken)features.optionalChainSites++;if(ts.isExportAssignment(n)&&!n.isExportEquals&&!ts.isIdentifier(n.expression))features.defaultExportExpressions++;ts.forEachChild(n,visit);};
  visit(parsed);
  row.emittedRuntimeHash=crypto.createHash('sha256').update(emitted).digest('hex');
 }
 row.runtimeFeatures=features;
 const allZero=row.metrics&&row.nonzeroMetrics.length===0;
 let disposition;
 if(row.syntax==='browser-code')disposition='Separate browser instrumentation and execution required; no JavaScript-runtime omission or exclusion approved.';
 else if(row.syntax==='no-local-code')disposition='No emitted local runtime computation and no counters observed; four zero-applicability judgments proposed individually, pending independent review. No percentage claimed.';
 else if(row.syntax==='re-export')disposition='Only dependency re-exports emitted; no local counters observed. Require real module loading/export wiring proof and separate dependency measurement. Zero local metrics remain unapproved.';
 else if(allZero&&features.defaultExportExpressions)disposition='Confirmed instrumentation blind spot: an executable default-export expression has zero statement/line counters. B05.1 must repair it; zero is not eligible for applicability approval.';
 else if(allZero)disposition='Value-import-only runtime shape has zero local counters. Resolve runtime import/type erasure and binding proof before approving any zero applicability; B05.2/B04 own disposition.';
 else disposition='Measure every positive denominator; individually review zero branch/function denominators against runtime syntax. Observed counts do not prove instrumentation completeness.';
 if(features.optionalChainSites)disposition+=' Optional-chain syntax is present; synthetic evidence shows current instrumentation omits its decision counters. B05.1 owns source-mapped branch proof before numeric acceptance.';
 file.metricApplicability={status:'proposed - independent review pending',evidence:root+'evidence/B04-applicability-probe.json',sourceHash:row.sourceHash,disposition,metrics:Object.fromEntries(['statements','branches','functions','lines'].map(metric=>[metric,row.metrics?{observedCounterTotal:row.metrics[metric].total,proposal:row.metrics[metric].total>0?'measure - completeness unverified':allZero&&row.syntax==='executable'?'blocked - runtime accounting unresolved':'zero requires individual review'}:{observedCounterTotal:null,proposal:'separate browser measurement required'}]))};
}
const tasks=[
 ['B05.1','Close instrumenter counter blind spots','scripts/run-istanbul-bun-coverage{,.test}.ts and source mapping','Measure default-export expression evaluation and optional-chain decisions without changing runtime behavior or losing original source locations. Preserve thrown errors, evaluation order, receiver binding, short-circuit side effects and default export identities.','RED/GREEN synthetic runtime cases for default expressions, calls/objects/anonymous values and optional property/element/call chains, null/undefined/present and unexecuted paths. Every real decision maps to source; no counter-based 100% for omitted execution. Tier S guards and applicable per-file metrics.'],
 ['B05.2','Select the complete source inventory for measurement','coverage runner inventory selection and evidence assembly','Replace src-only/test-ignore selection with the reviewed source-bound inventory. Account for scripts, actual test-driver logic, root configurations, deprecated CLI, unimported code and re-export/module wiring; resolve extraction port value-import versus type-erasure behavior without assuming either.','Real isolated fixture proves all supported paths are selected, unimported executable is uncovered, relative imports and CLI entry behavior remain intact, per-file evidence binds source, zero-only files require reviewed disposition and no blanket test/script exclusion.'],
 ['B05.3','Measure both browser-code documents','two explicitly listed HTML candidates and browser measurement adapter','Instrument inline scripts in each documented HTML candidate and collect real browser coverage with original HTML/script positions; retain document provenance and a bounded browser invocation. Do not execute report claims as code or treat browser omission as exclusion.','Actual browser clicks exercise every section/filter/lens control; missing inline scripts, failed invocation and unmappable positions fail admission. Prove emitted counters correspond to behavior, including both sides of filter decisions; bind artifact hashes and package ownership.']
];
for(const [id,title,scope,deliverable,verification] of tasks)ledger.items.push({id,stage:'baseline',title,status:'pending',depends_on:['B03','B04'],scope,deliverable,verification,risk:'S',authorization:'authorized',owner:'memory-nexus',evidence:[],acceptance_record:root+'evidence/'+id+'.json',observed_evidence:[root+'evidence/B04-applicability-probe.json',root+'evidence/B04-counter-boundary-probe.json'],retirement_trigger:'Before B05 completion and numerical baseline acceptance B07/B09/R02.'});
const b05=ledger.items.find(x=>x.id==='B05');
b05.depends_on.push(...tasks.map(x=>x[0]));b05.risk='S';b05.scope='Completion barrier for B05.1-B05.3; complete source/runtime measurement';b05.deliverable='Close source-accounting, zero-counter and separate-browser gaps through the individually verified child tasks; reconcile every catalog candidate before proceeding to revision-bound reports.';
const b04=ledger.items.find(x=>x.id==='B04');
b04.progress.metricApplicability='Individual four-metric candidate matrix recorded for all 446 sources; 444 statically instrumented without execution. Zero metrics and independent applicability judgments remain unapproved.';
b04.progress.next='Independent source-bound risk/applicability review; continue ready baseline fixture repairs if reviewer remains unavailable. B05 children own confirmed counter and selection defects.';
b04.evidence.push(root+'evidence/B04-applicability-probe.json',root+'evidence/B04-counter-boundary-probe.json',root+'B04-metric-applicability.md');
save(root+'quality-classifications.json',manifest);save(root+'work-items.json',ledger);
probe.summary={candidates:446,instrumentedWithoutExecution:444,separateBrowser:2,currentRunnerSelected:210,zeroCounterFiles:37,optionalChainFiles:probe.rows.filter(x=>x.runtimeFeatures.optionalChainSites).length,defaultExportExpressionFiles:probe.rows.filter(x=>x.runtimeFeatures.defaultExportExpressions).length};
probe.recordingSource=fs.readFileSync('.git/b04-record-applicability.mjs','utf8');
probe.sourceInputs=['quality-classifications.json','work-items.json'].map(p=>({path:root+p,sourceHash:hash(root+p)}));
save(root+'evidence/B04-applicability-probe.json',probe);save(root+'evidence/B04-counter-boundary-probe.json',boundary);
const edit=(p,fn)=>fs.writeFileSync(p,fn(fs.readFileSync(p,'utf8')));
edit('.planning/STATE.md',s=>s.replace('Next: remaining source risk/applicability decisions, then independent review.','All 446 files now have a four-metric candidate matrix. Static/runtime probes found selection and counter gaps owned by B05.1-B05.3. Next: independent risk/applicability review; ready fixture repairs can proceed while review is unavailable.').replace('215 items: 120 delivery/gates','218 items: 123 delivery/gates'));
edit(root+'EXECUTION.md',s=>s.replace('| Safe verification | B01-B08 |','| Safe verification | B01-B08, including B05.1-B05.3 |'));
edit(root+'B04-inventory-plan.md',s=>s+'\n## Metric applicability checkpoint\n\nSee [B04-metric-applicability.md](B04-metric-applicability.md) and the per-file\n`metricApplicability` entries. All 444 JavaScript/TypeScript candidates were\nstatically instrumented without evaluating candidate modules. The two browser\ndocuments retain their separate runtime obligation. Real synthetic VM probes\nconfirmed default-export and optional-chain counter blind spots. B05.1-B05.3\nown repairs; neither an empty denominator nor the complete candidate matrix\napproves applicability. Independent review remains pending.\n');
edit(root+'JOURNAL.md',s=>s.replace('# Memory resilience execution journal','# Memory resilience execution journal\n\n## 2026-09-20 - B04 metric applicability and counter diagnostics\n\n- Previous turn progressed: e5c6908 completed proposed risk tiers and fixture\n  repair dependencies; the working tree was clean at this turn start.\n- Ran static instrumentation on all 444 JS/TS candidates without executing them;\n  retained per-file four-metric counts/hashes. Two HTML documents need browser\n  measurement. Current runner selection covers only 210 catalog candidates.\n- Found 37 zero-counter files: 11 type-only, 23 re-export, one value-import-only\n  port and two executable configs. Zero is not automatically not-applicable.\n- Executed four synthetic in-memory VM cases. Default-export calls execute with\n  zero statements; optional access yields zero branches while an explicit null\n  conditional yields two. Library summary emits 100% for empty denominators;\n  this does not assert that the current aggregate threshold gate accepts them.\n- Added atomic B05.1 counter repair, B05.2 inventory selection and B05.3 browser\n  measurement. B05 is their completion barrier and remains pending on B04.\n  Ledger has 218 items (123 delivery/gates, 95 quality candidates).\n- Every candidate has four proposed metric dispositions. All zero decisions and\n  independent risk/applicability review remain open; no exclusions approved.\n- Next: independent review and ready fixture repairs while reviewer route is\n  quota-blocked. No candidate module, full suite, model or production memory ran.\n'));
edit(root+'B04-source-findings.md',s=>s+'\n## Instrumentation and applicability findings\n\nB05.1 owns experimentally confirmed default-export and optional-chain counter\nblind spots. B05.2 owns src-only selection (210 of 446 catalog candidates) and\nmodule-wiring/zero-only source accounting. B05.3 owns the two HTML runtime\nmeasurement paths. Their source-bound and synthetic evidence is retained in\n`B04-applicability-probe.json` and `B04-counter-boundary-probe.json` under evidence.\nB05 is an explicit completion barrier; B07/B09/R02 cannot bypass these tasks.\nThe library reporting 100% for a zero denominator is not a claim that the current\naggregate checker admits that individual file; it is a reason to reject such\nevidence in the planned per-file gate. No existing per-file acceptance is claimed.\n');
edit('.git/memory-resilience-pr-body.md',s=>s.replace('215-item','218-item').replace('215 items: 120 delivery/gates','218 items: 123 delivery/gates').replace(/- Latest documentation checkpoint[^\n]+/,'- Latest applicability checkpoint statically instruments all 444 JS/TS candidates and records four-metric proposals for all 446 files. Current selection reaches 210; 37 files have no counters. Four synthetic VM cases reproduce default-export statement and optional-chain branch blind spots. B05.1-B05.3 block acceptance until counter, selection and browser measurement repairs pass. No candidate module or full suite was executed.').replace('individual metric applicability and independent tier review are unfinished','the per-file metric candidate matrix is recorded, while zero-applicability judgments and independent review remain unfinished'));
console.log(JSON.stringify(probe.summary));
